+
+	// Spool model events until the static result is known. The evidence clock and
+	// attempt stay those of this submission; transport accounting is never discarded.
+	ev := sh.ev
+	modelDir := filepath.Join(ev.Dir, fmt.Sprintf("post-submit-models-%d", sh.submissions))
+	if err := os.RemoveAll(modelDir); err != nil {
+		return err
+	}
+	modelEV, err := NewEvidenceWithClock(modelDir, sh.slug, ev.Now)
+	if err != nil {
+		return err
+	}
+	modelEV.origin, modelEV.timestamp, modelEV.attempt = ev.origin, ev.timestamp, ev.attemptNow()
+	sh.ev = modelEV
+	defer func() { sh.ev = ev }()
+	marks, notes := sh.pendingMarks, sh.notes
+	statements := maps.Clone(sh.refusedStatements)
+
+	ctx, cancel := context.WithCancel(ctx)
+	defer cancel()
+	var once sync.Once
+	var first error
+	fail := func(err error) {
+		if err != nil {
+			once.Do(func() { first = err; cancel() })
+		}
+	}
+	head := sh.repo.Head()
+	tree, err := sh.repo.Tree(head, nil)
+	if err != nil {
+		return err
+	}
+	run := sh.staticLast
+	reused := run != nil && run.Head == head && run.Tree == tree
+	var staticErr error
+	var wg sync.WaitGroup
+	wg.Add(1)
+	go func() {
+		defer wg.Done()
+		if reused {
+			sh.progress(fmt.Sprintf("kogen: static checks: the candidate is unchanged since submission %d; their result stands", run.attempt))
+			return
+		}
+		g := newStaticGateRunner(sh.s, sh.repo, sh.rd, sh.cfg, sh.root, sh.slug, sh.progress)
+		g.judged = sh.bareProgress
+		run, staticErr = g.run(ctx, head, tree, hash)
+		fail(staticErr)
+	}()
+	refusals, modelErr := runModelChecks(ctx,
 		func(ctx context.Context) ([]string, error) {
 			return sh.decisionCheckWithEvidence(ctx, intent, evidence)
-		},
-		sh.literalCheck, sh.exampleCheck)
-	if err != nil {
-		return err
+		}, sh.literalCheck, sh.exampleCheck)
+	fail(modelErr)
+	wg.Wait()
+	if staticErr == nil {
+		if !reused {
+			run.attempt = sh.submissions
+			sh.staticLast = run
+			if err := writeStaticRecord(sh.root, sh.slug, run); err != nil {
+				fail(err)
+			}
+		}
+		ev.Record(map[string]any{"event": "static_checks", "attempt": sh.submissions, "outcome": run.Outcome, "reused": reused, "dir": run.Dir,
+			"head": run.Head, "tree": run.Tree, "sha256": run.SHA256, "files": run.Files, "checks": run.Checks, "copy_ms": run.CopyMS})
+	}
+	// Preserve call evidence, including wasted calls, but publish gate answers only
+	// for a statically eligible package, in decision/literal/example order.
+	data, readErr := os.ReadFile(filepath.Join(modelDir, "events.ndjson"))
+	fail(readErr)
+	gateEvents := map[string][]map[string]any{}
+	for _, line := range bytes.Split(data, []byte("\n")) {
+		if len(line) == 0 {
+			continue
+		}
+		var event map[string]any
+		if err := json.Unmarshal(line, &event); err != nil {
+			fail(err)
+			continue
+		}
+		name, _ := event["event"].(string)
+		if slices.Contains([]string{"decision_check", "literal_check", "example_check"}, name) {
+			gateEvents[name] = append(gateEvents[name], event)
+		} else {
+			ev.Record(event)
+		}
+	}
+	for phase, spans := range modelEV.intervals {
+		for _, span := range spans {
+			ev.Interval(phase, span[0], span[1])
+		}
+	}
+	if first != nil {
+		return first
+	}
+	if run.Outcome == staticRefused {
+		sh.pendingMarks, sh.notes, sh.refusedStatements = marks, notes, statements
+		headline, problems := run.refusal()
+		sh.refused(staticGate, problems)
+		sh.holdText(headline + "\n" + strings.Join(problems, "\n"))
+		return nil
+	}
+	for _, name := range []string{"decision_check", "literal_check", "example_check"} {
+		for _, event := range gateEvents[name] {
+			ev.Record(event)
+		}
 	}
 	for _, r := range refusals {
 		sh.refused(r.gate, r.problems())

